    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Mark the large monochrome rectangular patches; the surrounding cells are noise.
    for r0 in range(h):
        for r1 in range(r0+4,h):
            common=[True]*w
            for r in range(r0,r1+1):
                for c in range(w):
                    if grid[r][c]!=grid[r0][c]: common[c]=False
